import React, { useState } from "react";
import { Button, Switch, Input, Select, message } from "antd";
import { RedoOutlined } from "@ant-design/icons";
import "../css/footer.css";
import useStore from "../store";
import player from "../img/player.png";
const Footer = () => {
  const [saveText, setSaveText] = useState("保存并上传");
  const [showSave, setShowSave] = useState(false);
  const [showPlayer, setShowPlayer] = useState(false);
  const [isUpload, setIsUpload] = useState(true);
  const { img, isModified, setIsModified, setImg } = useStore();
  const [messageApi, contextHolder] = message.useMessage();
  const reset = () => {
    setImg(player);
    setIsModified(false);
  };
  const onchange = (key) => {
    setSaveText(key ? "保存并上传" : "保存");
    setIsUpload(key);
  };

  const handleUpload = () => {
    setShowSave(false);
    setShowPlayer(true);
    messageApi.info("模板已上传");
  };
  const handleSave = () => {
    if (isUpload) setShowSave(true);
    else {
      handleUpload();
    }
  };
  return (
    <div className="footer">
      {contextHolder}
      {showPlayer && (
        <div
          className="completePlayer"
          onClick={() => setShowPlayer(false)}
          style={{ backgroundImage: `url(${img})` }}
        ></div>
      )}
      {showSave && (
        <div className="tips">
          <div className="tips_content">
            <div className="tips_content_title">
              <div className="tips_line">
                <div>模板标题：</div>
                <Input placeholder="小红的模板" size="small"></Input>
              </div>
              <div className="tips_line">
                <div>模板标题：</div>
                <Select
                  defaultValue="lucy"
                  size="small"
                  options={[
                    { value: "jack", label: "经典" },
                    { value: "lucy", label: "明星" },
                    { value: "Yiminghe", label: "动漫" },
                    { value: "disabled", label: "创意" },
                  ]}
                />
              </div>
            </div>
            <Button
              color="green"
              variant="solid"
              size="small"
              onClick={handleUpload}
              style={{ margin: "40px 0 16px" }}
            >
              上传
            </Button>
            发布将自动签署 QQ音乐创作者服务协议
          </div>
        </div>
      )}
      <div className="footer_content">
        <div className="reset icon-container" onClick={reset}>
          <RedoOutlined />
          重置
        </div>
        <Button color="green" variant="solid" onClick={handleSave}>
          {saveText}
        </Button>
        <div className="isUpload icon-container">
          <Switch
            size="small"
            defaultChecked
            onChange={onchange}
            disabled={isModified}
          />
          上传
        </div>
      </div>
    </div>
  );
};

export default Footer;
