import React, { useState } from "react";
import "../css/tabSetting.css";

const COLOR_LIST = [
  "#ffffff",
  "#FF7A78",
  "#000000",
  "#FF4948",
  "#FF0200",
  "#D61113",
  "#AC0000",
  "#FFE678",
  "#FAC000",
  "#FF9700",
  "#FF6A00",
  "#FF5100",
  "#ACE77D",
  "#88FF6B",
  "#27FF00",
  "#92FF15",
];
const TabSetting = () => {
  const [currentConfig, setCurrentConfig] = useState("#ffffff");
  const handleColorSelect = (color) => {
    setCurrentConfig(color);
  };
  const blackGlassList = [
    {
      id: 1,
      url: "#000000",
    },
    {
      id: 2,
      url: "#555555",
    },
  ];
  return (
    <div className="">
      <div className="setting-section">
        <div className="setting-title">背景颜色</div>
        <div className="color-options">
          {COLOR_LIST.map((color, index) => {
            return (
              <div
                className={`color-swatch ${
                  currentConfig === color ? "selected" : ""
                }`}
                onClick={() => handleColorSelect(color)}
                key={index}
              >
                <div
                  className="color-item"
                  style={{ backgroundColor: color }}
                ></div>
              </div>
            );
          })}
        </div>
      </div>
      <div className="setting-section">
        <div className="setting-title">文字按钮颜色</div>
        <div className="text-color-options">
          {COLOR_LIST.map((color, index) => {
            return (
              <div
                className={`color-swatch ${
                  currentConfig === color ? "selected" : ""
                }`}
                onClick={() => handleColorSelect(color)}
                key={index}
              >
                <div
                  className="color-item"
                  style={{ backgroundColor: color }}
                ></div>
              </div>
            );
          })}
        </div>
        <div className="touchBar"></div>
      </div>
      <div className="setting-section">
        <div className="setting-title">黑胶底板</div>
        <div className="black-glass-container">
          {blackGlassList.map((item) => {
            return (
              <div
                className="black-glass-item"
                key={item.id}
                style={{ backgroundColor: item.url }}
              ></div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default TabSetting;
