import React from "react";
import "../css/more.css";
import bg from "../img/store.png";
import useStore from "../store";
const More = () => {
  const { setShowContent } = useStore();
  return (
    <div
      className="more"
      style={{ backgroundImage: `url(${bg})` }}
      onClick={() => setShowContent(0)}
    ></div>
  );
};

export default More;
