import React from "react";
import TabSetting from "./tabSetting";
import TabHot from "./tabHot";
import More from "./more";
import "../css/content.css";
import useStore from "../store";
const Content = () => {
  const { img, showContent, setShowContent } = useStore();
  const items = [
    {
      key: 0,
      label: "自定义",
      children: <TabSetting />,
    },
    {
      key: 1,
      label: "热门",
      children: <TabHot />,
    },
    {
      key: 2,
      label: "经典",
      children: <TabHot />,
    },
    {
      key: 3,
      label: "明星",
      children: <TabHot />,
    },
    {
      key: 4,
      label: "动漫",
      children: <TabHot />,
    },
    {
      key: 5,
      label: "古风",
      children: <TabHot />,
    },
    {
      key: 6,
      label: "赛博",
      children: <TabHot />,
    },
    {
      key: 7,
      label: "更多",
      children: <More />,
    },
  ];
  const onChange = (key) => {
    setShowContent(key);
  };
  return (
    <div className="content">
      <div
        className="background"
        style={{ backgroundImage: `url(${img})` }}
      ></div>
      <div className="setting">
        <div className="setting_tabs_container">
          {items.map((item) => (
            <div
              key={item.key}
              className={
                showContent === item.key
                  ? "setting_tab setting_tab_active"
                  : "setting_tab"
              }
              onClick={() => onChange(item.key)}
            >
              {item.label}
            </div>
          ))}
        </div>
        <div className="setting_tabs_content">
          {items[showContent].children}
        </div>
      </div>
    </div>
  );
};

export default Content;
